using UnityEngine; namespace Mojinloop.Gameplay { public enum HeroState{Idle,Running,Attacking,Dead} public sealed class HeroController:MonoBehaviour { public HeroState State{get;private set;}=HeroState.Idle; public void SetState(HeroState state){if(State==HeroState.Dead)return;State=state;transform.localScale=state==HeroState.Attacking?new Vector3(1.12f,.9f,1):Vector3.one;} public void Die()=>State=HeroState.Dead; } }
